class Expectation(BaseModel):
    """
    An expectation row as returned from the database: a **wait** that Tasks can depend on.

    It carries a Time Scope and tags, like a Task. Note what is absent, since the absences are the
    design: no Plan and no On-exit behaviour (a wait is not something you schedule, and it is never
    Missed), no block reasons and no dependencies of its own — it depends on nothing,
    only Tasks depend on it. Beside its Time Scope it carries the optional **Check every**.
    """

    agentic: bool
    """
    Whether an **agent** raised this wait on the agentic Task it hangs under: "the agent is
    waiting on you" — or, when it is not a [`question`](Self::question), waiting on something
    else, like CI. Released like any wait; a question wait only with an answer.
    """
    agentic_note: str | None
    """
    An agentic wait's note: the agent's question, or what it is waiting for. `None` for none.
    """
    answer: str | None
    """
    The answer a question wait was released with, or is being given. `None` for none.
    """
    archival: ExpectationArchival
    """
    Live or Archived, independently of the status.
    """
    check_every: DurationSpec | None = None
    """
    How often to look in on it, if ever — a counted Duration. While it is set and the wait is
    pending, a virtual "check on it" task is due at [`Self::check_starting`], and after each
    check one interval after that check was made. Nothing is stored for a check but its time.
    """
    check_starting: datetime | None = None
    """
    When the first check falls due; set to the moment Check every is first given, unless the
    request names another.
    """
    id: int | str
    """
    Primary key for a stored wait, or the UUID of a derived one (a Task's spawned wait, or a
    delegated Task's wait on its delegate).
    """
    is_private: bool
    """
    Whether this node is private (hidden unless Private Mode is on).
    """
    last_check_at: datetime | None = None
    """
    When the last check was made, if any. The next falls due one interval after it.
    """
    origin: (
        OriginManual
        | OriginHabit
        | OriginCheck
        | OriginSpawnedWait
        | OriginDelegationWait
    )
    """
    Where the row came from: made by hand, or derived from a Task (ADR 0008).
    """
    parent_id: int | str
    """
    Id of the parent entity: a stored row, or a derived one (a Habit occurrence).
    """
    parent_type: str
    """
    Type of the parent entity.
    """
    position: int
    """
    Sort position among siblings.
    """
    question: bool
    """
    Whether an agentic wait is a **question** — the agent asking the user — rather than a wait
    on something non-human, like CI. A question wait is released only with an [`answer`]
    (`Self::answer`). Meaningless on a wait that is not agentic.
    """
    status: ExpectationStatus
    """
    Pending or Released.
    """
    tag_ids: list[int]
    """
    Tag domain ids attached to this expectation.
    """
    time_scope: TimeScope | None
    """
    Relevance window, if set. Its own only: a wait's window is validated against its nearest
    scoped ancestor's, but not inherited from it.
    """
    title: str
    """
    Display title.
    """


class Goal(BaseModel):
    """
    A goal row as returned from the database.
    """

    id: int | str
    """
    Primary key for a stored row, or the UUID of a derived one.
    """
    is_private: bool
    """
    Whether this node is private (hidden unless Private Mode is on).
    """
    on_scope_exit: OnScopeExit | None
    """
    On-exit behavior; present iff `time_scope` is (inherited with the window otherwise).
    """
    origin: (
        OriginManual
        | OriginHabit
        | OriginCheck
        | OriginSpawnedWait
        | OriginDelegationWait
    )
    """
    Where the row came from: made by hand, or derived (a Habit occurrence).
    """
    parent_id: int | str
    """
    Id of the parent entity: a stored row, or a derived one (a Habit occurrence).
    """
    parent_type: str
    """
    Type of the parent entity.
    """
    position: int
    """
    Sort position among siblings; defaults to id (insertion order).
    """
    status: str
    """
    Current status.
    """
    tag_ids: list[int]
    """
    Tag domain ids attached to this goal.
    """
    time_scope: TimeScope | None
    """
    Relevance window (if set). A null value inherits the nearest scoped ancestor.
    """
    title: str
    """
    Display title.
    """


class HabitOrigin(BaseModel):
    """
    A Habit occurrence's provenance: which Habit, which iteration, which template row and pair.
    """

    cycle_id: int
    """
    The cycle pair that drew it, or `0`.
    """
    habit_id: int
    """
    The Habit (flow) the occurrence belongs to.
    """
    item_id: int
    """
    The template row's id (the flow's own for the root).
    """
    item_type: TemplateKind
    """
    The template table the occurrence is drawn from — `flow_root` for the iteration's root.
    """
    iteration_scope: IterationScope
    """
    The iteration the occurrence is in.
    """


class MindmapLoad(BaseModel):
    """
    Everything one mindmap render reads, gathered in a single command round trip.

    Each field is exactly what the equivalent single-resource command returns; this type adds no
    derived or assembled data. Tree assembly stays in the frontend (see the Phase 6 scope note in
    `docs/superpowers/plans/2026-09-13-backend-architecture-foundations.md`).
    """

    agent_activity: AgentActivity | None = None
    """
    What the agents are doing on the whole board. Filled by the app's load only.
    """
    block_reasons: list[BlockReason]
    """
    Every block reason across tasks and goals — as `list_all_block_reasons`.
    """
    commitments: list[Commitment]
    """
    Every commitment, stored and derived — the Commitment virtual table.
    """
    domains: list[Domain]
    """
    Aspects, projects, domains and tags — as `list_domains(None)`.
    """
    expectations: list[Expectation]
    """
    Every expectation, stored and derived — the Expectation virtual table: a Task's spawned
    wait and a delegated Task's wait are rows here, told apart by their `origin`. A wait's
    check tasks are rows of `tasks`.
    """
    facts: dict[str, NodeFacts] | None = None
    """
    What the board says about each node beyond its own row, keyed as [`Self::short_ids`] is:
    which of its dependencies block it, what it inherits, its open question, whether it has
    expired. Filled by the app's load only, as [`Self::short_ids`] is.
    """
    flow_cycles: list[FlowItemCycle]
    """
    Every flow's cycle pairs — as `list_all_flow_cycles`.
    """
    flow_dependencies: list[FlowDependency]
    """
    Every flow's intra-flow dependencies — as `list_all_flow_dependencies`.
    """
    flow_goals: list[FlowGoal]
    """
    Every flow's goal items — as `list_all_flow_goals`.
    """
    flow_instance_nodes: list[TargetRef]
    """
    Every real node materialised by a started flow — as `list_flow_instance_nodes`.
    """
    flow_tasks: list[FlowTask]
    """
    Every flow's task items — as `list_all_flow_tasks`.
    """
    flows: list[Flow]
    """
    Every flow — as `list_flows`.
    """
    goals: list[Goal]
    """
    Every goal, stored and derived — the Goal virtual table.
    """
    habits: list[FlowHabitEntry]
    """
    One entry per flow, in `flows` order — the dependent wave, resolved backend-side.
    """
    infos: list[Info]
    """
    Every info node — as `list_infos`.
    """
    lifecycles: list[ItemLifecycle]
    """
    Every task's, goal's and commitment's derived lifecycle at `now`, derived rows included.
    """
    short_ids: dict[str, str] | None = None
    """
    Each Task's, Goal's, Commitment's and wait's **short id** on the whole board, keyed as the
    board keys a node (`task-12`): what the app names a dependency it is blocked by with.
    Filled by the app's load only (the app crate's `commands::mindmap::load_mindmap`); empty, and left
    off the wire, everywhere else — the MCP names nodes among those it can see.
    """
    task_dependencies: list[TaskDependencyEdge]
    """
    Every task dependency edge — as `list_all_task_dependencies`.
    """
    tasks: list[Task]
    """
    Every task, stored and derived — the Task virtual table. A Habit occurrence is one of
    these like any other, told apart only by its `origin`.
    """


class StatusStepOutcomeWritten(BaseModel):
    """
    The status was written. `backlog_cleared` says, when it did, that the write took the Task
    out of the Backlog — which the frontend says out loud.
    """

    backlog_cleared: BacklogCleared | None
    """
    How the write took it out of the Backlog, if it did.
    """
    outcome: Literal["written"]
    task: Task
    """
    The Task as the write left it.
    """


class StatusStepOutcome(RootModel[StatusStepOutcomeWritten | StatusStepOutcomeRefused]):
    root: StatusStepOutcomeWritten | StatusStepOutcomeRefused
    """
    What a status gesture did.
    """


class DuplicatedGoal(BaseModel):
    """
    A duplicate command's answer: the copy's root, and what the copy left behind.
    """

    copy_: Annotated[Goal, Field(alias="copy")]
    """
    The copy's root, as its own table returns it.
    """
    left_behind: list[LeftBehindChild]
    """
    The rows hung on Habit occurrences the copy could not carry, for the paste to name.
    """


# The tagged unions, by the names the Rust types have.
FlowHabitResult: TypeAlias = FlowHabitResultLoaded | FlowHabitResultFailed
Origin: TypeAlias = OriginManual | OriginHabit | OriginCheck | OriginSpawnedWait | OriginDelegationWait
ScopeKey: TypeAlias = ScopeKeySeason | ScopeKeyMonth | ScopeKeyWeek | ScopeKeyDay | ScopeKeyPartOfDay | ScopeKeyExact
Status: TypeAlias = StatusOrdinary | StatusAgentic
